import {
  createSource,
  type FumadocsCollection,
} from '@vercel/geistdocs/source';
import { config } from './config';

export type SearchVersion = 'v5' | 'v6' | 'v7';

/** Content families of a version, in the order `source.ts` lists them. */
const families = ['docs', 'providers', 'cookbook'] as const;

type SearchFiles = ReturnType<FumadocsCollection['toFumadocsSource']>['files'];
type SearchIndex = Record<(typeof families)[number], SearchFiles>;

// One module per version, generated by scripts/build-search-index.mjs. Each
// holds the frontmatter and search sections of that version's pages, without
// the compiled MDX that `source.ts` imports for every version (~110 MB).
// They load on demand so an instance only pays for the version it searches.
const searchIndexes: Record<
  SearchVersion,
  () => Promise<{ default: SearchIndex }>
> = {
  v5: () => import('@/.search-index/v5'),
  v6: () => import('@/.search-index/v6'),
  v7: () => import('@/.search-index/v7'),
};

/**
 * The sources `/api/search` indexes for a version. They resolve the same
 * pages, URLs, and page tree as `v5Sources`, `v6Sources`, and `v7Sources` in
 * `source.ts`, which is why the base URLs below must match that file.
 */
export const loadSearchSources = async (version: SearchVersion) => {
  const { default: index } = await searchIndexes[version]();
  const routePrefix = version === 'v7' ? '' : `/${version}`;

  return families.map(family =>
    createSource({
      config,
      docs: { toFumadocsSource: () => ({ files: index[family] }) },
      baseUrl: `${routePrefix}/${family}`,
      id: version,
      label: version,
    }),
  );
};
